update country_flag_history set label_fr = 'Empire russe (noir-jaune-blanc)', label_en = 'Russian Empire (black-yellow-white)', notes_fr = 'Alexandre II adopte en 1858 un drapeau impérial noir, jaune et blanc, aux couleurs des armoiries ; il coexiste avec le blanc-bleu-rouge des navires marchands.', notes_en = 'Alexander II adopted an imperial black, yellow and white flag in 1858, in the colours of the arms; it coexisted with the white-blue-red of merchant ships.' where id = 2480 and iso_code = 'ru';
update country_flag_history set label_fr = 'Empire russe (blanc-bleu-rouge)', label_en = 'Russian Empire (white-blue-red)', notes_fr = 'Peu avant le couronnement de Nicolas II, le blanc-bleu-rouge hérité de Pierre le Grand est déclaré drapeau national en 1896.', notes_en = 'Shortly before Nicholas II''s coronation, the white-blue-red inherited from Peter the Great was declared the national flag in 1896.' where id = 2481 and iso_code = 'ru';
update country_flag_history set label_fr = 'RSFS de Russie (1918-1937)', label_en = 'Russian SFSR (1918–1937)', notes_fr = 'La république soviétique adopte un drapeau rouge portant au canton ses initiales en lettres cyrilliques.', notes_en = 'The Soviet republic adopted a red flag bearing its initials in Cyrillic letters in the canton.' where id = 2482 and iso_code = 'ru';
update country_flag_history set label_fr = 'RSFS de Russie (1937-1954)', label_en = 'Russian SFSR (1937–1954)', notes_fr = 'La Constitution de 1937 simplifie le drapeau : seules restent au canton les lettres dorées « РСФСР ».', notes_en = 'The 1937 Constitution simplified the flag: only the gold letters "РСФСР" remained in the canton.' where id = 2483 and iso_code = 'ru';
update country_flag_history set date_start = '1954-01-09', label_fr = 'RSFS de Russie (1954-1991)', label_en = 'Russian SFSR (1954–1991)', notes_fr = 'Comme les autres républiques, la RSFSR reçoit en 1954 un drapeau distinct de celui de l''URSS, avec une bande bleue le long de la hampe.', notes_en = 'Like the other republics, the RSFSR received in 1954 a flag distinct from the USSR''s, with a blue band along the hoist.', image_url = '/flags/history/ru-1954-2.svg' where id = 2252 and iso_code = 'ru';
update country_flag_history set label_fr = 'Fédération de Russie (1991-1993)', label_en = 'Russian Federation (1991–1993)', notes_fr = 'Le blanc-bleu-rouge est rétabli le 22 août 1991, au lendemain de l''échec du putsch de Moscou ; un décret de 1993 fixe le drapeau actuel.', notes_en = 'White-blue-red was restored on 22 August 1991, just after the failed Moscow coup; a 1993 decree set the current flag.' where id = 2484 and iso_code = 'ru';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ru', '/flags/history/ru-1923.svg', '1923-07-06', '1991-12-26', 'Union soviétique', 'Soviet Union', 'Drapeau rouge à la faucille, au marteau et à l''étoile dorés de l''URSS, dont la Russie était la principale république ; il est amené du Kremlin le 25 décembre 1991.', 'The red flag with the gold hammer, sickle and star of the USSR, of which Russia was the main republic; it was lowered from the Kremlin on 25 December 1991.');
